const transactions = $json.transactions || [];

return transactions.map(transaction => ({
  json: {
    blockchain: transaction.blockchain,
    transaction_hash: transaction.transaction_hash,
    timestamp: transaction.timestamp,
    asset: transaction.asset,
    sender: transaction.sender,
    receiver: transaction.receiver,
    amount: Number(transaction.amount || 0),
    price_usd: Number(transaction.price_usd || 0),
    status: transaction.status || "unknown"
  }
}));

const transactions = $items("Normalize Transaction Data");
const whaleRecords = $items("Load Tracked Whale Wallets");
const exchangeRecords = $items("Load Exchange Wallet Registry");

const whales = new Map();
const exchanges = new Map();

for (const item of whaleRecords) {
  const d = item.json;
  const address = String(d.wallet_address || "").toLowerCase();
  if (address && d.active !== false) {
    whales.set(address, { name: d.wallet_name || "Unknown Whale" });
  }
}

for (const item of exchangeRecords) {
  const d = item.json;
  const address = String(d.wallet_address || "").toLowerCase();
  if (address && d.active !== false) {
    exchanges.set(address, { name: d.exchange_name || "Unknown Exchange" });
  }
}

const output = [];

for (const item of transactions) {
  const tx = item.json;
  const sender = String(tx.sender || "").toLowerCase();
  const receiver = String(tx.receiver || "").toLowerCase();

  const senderWhale = whales.get(sender);
  const receiverWhale = whales.get(receiver);
  const senderExchange = exchanges.get(sender);
  const receiverExchange = exchanges.get(receiver);

  let movementType = "Unknown";
  let direction = "Unknown";
  let whaleWallet = "";
  let counterpartyWallet = "";
  let counterpartyName = "";

  if (senderWhale && receiverExchange) {
    movementType = "Exchange Deposit";
    direction = "Whale to Exchange";
    whaleWallet = sender;
    counterpartyWallet = receiver;
    counterpartyName = receiverExchange.name;
  } else if (senderExchange && receiverWhale) {
    movementType = "Exchange Withdrawal";
    direction = "Exchange to Whale";
    whaleWallet = receiver;
    counterpartyWallet = sender;
    counterpartyName = senderExchange.name;
  } else if (senderWhale && !receiverWhale && !receiverExchange) {
    movementType = "Wallet-to-Wallet";
    direction = "Whale to Wallet";
    whaleWallet = sender;
    counterpartyWallet = receiver;
    counterpartyName = "Unknown Wallet";
  } else if (!senderWhale && !senderExchange && receiverWhale) {
    movementType = "Wallet-to-Wallet";
    direction = "Wallet to Whale";
    whaleWallet = receiver;
    counterpartyWallet = sender;
    counterpartyName = "Unknown Wallet";
  } else {
    continue;
  }

  output.push({
    json: {
      ...tx,
      movement_type: movementType,
      direction,
      whale_wallet: whaleWallet,
      counterparty_wallet: counterpartyWallet,
      counterparty_name: counterpartyName
    }
  });
}

return output;

const amount = Number($json.amount || 0);
const priceUsd = Number($json.price_usd || 0);
const usdValue = amount * priceUsd;

let initialInterpretation = "Neutral whale movement";

if ($json.movement_type === "Exchange Deposit") {
  initialInterpretation = "Possible sell pressure building";
} else if ($json.movement_type === "Exchange Withdrawal") {
  initialInterpretation = "Possible accumulation or exchange outflow";
} else if ($json.movement_type === "Wallet-to-Wallet") {
  initialInterpretation = "Possible whale repositioning";
}

return [{
  json: {
    ...$json,
    usd_value: Number(usdValue.toFixed(2)),
    alert_threshold: 100000,
    alert_eligible: usdValue >= 100000,
    initial_interpretation: initialInterpretation
  }
}];

