const response = $json;
const source = response.choices && response.choices[0] && response.choices[0].message
  ? response.choices[0].message.content
  : "";

let interpretation = "";
let confidence = 50;

try {
  const parsed = JSON.parse(String(source).replace(/```json/g, "").replace(/```/g, "").trim());
  interpretation = String(parsed.interpretation || "");
  confidence = Number(parsed.confidence || 50);
} catch (error) {
  interpretation = String(source || "No AI interpretation returned.");
}

const original = $items("Calculate Transaction Value")[0].json;

return [{
  json: {
    ...original,
    ai_interpretation: interpretation,
    ai_confidence: Math.max(0, Math.min(100, confidence))
  }
}];
